from qa_check import decode_png
w, h, px = decode_png('output/pelican-skateboard.svg.png')

def find(rgb, tol=4, step=2):
    ys, xs = [], []
    for y in range(0, h, step):
        for x in range(0, w, step):
            p = px[y][x]
            if all(abs(a-b) <= tol for a, b in zip(p[:3], rgb)):
                ys.append(y); xs.append(x)
    return ys, xs

# sea top color and sea bottom color
for name, rgb in [('sea-top (91,198,234)', (91,198,234)), ('sea-bot (30,136,184)', (30,136,184)),
                  ('edge (168,122,77)', (168,122,77))]:
    ys, xs = find(rgb)
    if ys:
        print(f'{name}: y[{min(ys)},{max(ys)}] x[{min(xs)},{max(xs)}] n={len(ys)}')
    else:
        print(f'{name}: NOT FOUND')

# vertical scan at x=100 (far left, svg x~67) to list band colors
print('\ncolumn scan at x=100 (png):')
last = None
for y in range(0, h, 3):
    c = px[y][100]
    if last is None or sum(abs(a-b) for a,b in zip(c[:3], last[:3])) > 30:
        print(f'  y={y}: {c[:3]}')
        last = c
